# PROMPT: Write a python script called "run_regressions" which runs a verilator 
# command for every test bench (changing the --top flag each time) and verifies no 
# early termination due to failing testbenches. Otherwise, it outputs what test failed

"""Build and run the existing testbenches: python3 run_regressions.py."""
from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parent
# Expected scoreboard comparisons catch tests that finish before checking everything.
TESTS = {
    "tb_systolic_array": 64,
    "tb_instrumentation": 64,
    "tb_ram": 1,
    "tb_uart_rx": 12,
}


def run_test(top, expected_passes):
    build_dir = ROOT / "obj_dir" / top
    build_dir.mkdir(parents=True, exist_ok=True)
    command = [
        "verilator", "--binary", "--timing", "--Wno-WIDTH", "--Wno-TIMESCALEMOD",
        "--top", top, "--Mdir", str(build_dir),
        *[str(path) for path in sorted((ROOT / "rtl").glob("*.sv"))],
        str(ROOT / "tb" / f"{top}.sv"),
    ]
    build_log = build_dir / "build.log"
    simulation_log = build_dir / "simulation.log"
    try:
        with build_log.open("w") as output:
            result = subprocess.run(
                command, cwd=ROOT, stdout=output, stderr=subprocess.STDOUT, timeout=180,
            )
        if result.returncode:
            return f"build failed (exit {result.returncode}); see {build_log.relative_to(ROOT)}"

        with simulation_log.open("w") as output:
            result = subprocess.run(
                [str(build_dir / f"V{top}")], cwd=ROOT,
                stdout=output, stderr=subprocess.STDOUT, timeout=30,
            )
    except subprocess.TimeoutExpired:
        return f"command timed out; see {build_dir.relative_to(ROOT)}"
    except OSError as error:
        return str(error)

    text = simulation_log.read_text(errors="replace")
    log_path = simulation_log.relative_to(ROOT)
    if result.returncode:
        return f"simulation failed (exit {result.returncode}); see {log_path}"
    for line in text.splitlines():
        if "[FAIL]" in line or "%Error" in line or "%Fatal" in line or "timeout" in line.lower() or "timed out" in line.lower():
            return f"{line.strip()}; see {log_path}"
    passed = text.count("[SCOREBOARD][PASS]")
    if passed != expected_passes:
        return f"incomplete checks: {passed}/{expected_passes} passed; see {log_path}"
    if "Verilog $finish" not in text:
        return f"simulation did not finish normally; see {log_path}"
    return None


def main():
    failed = []
    for top, expected_passes in TESTS.items():
        print(f"Running {top}...", flush=True)
        error = run_test(top, expected_passes)
        if error:
            failed.append(top)
            print(f"FAIL: {top}: {error}", flush=True)
        else:
            print(f"PASS: {top}", flush=True)

    # PROMPT: Write a modification at the end which moves .vcd files into a "build_artifacts" directory
    artifacts = ROOT / "build_artifacts"
    artifacts.mkdir(exist_ok=True)
    for waveform in ROOT.glob("*.vcd"):
        waveform.replace(artifacts / waveform.name)

    if failed:
        print("Failed tests: " + ", ".join(failed))
        return 1
    print("All testbenches passed.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
